# Write conf\frps.toml from the app's settings.
. (Join-Path $PSScriptRoot 'lib.ps1')
. (Join-Path $PSScriptRoot 'frp.ps1')

function Get-Setting([string]$Name, [string]$Default) {
    $v = [Environment]::GetEnvironmentVariable($Name)
    if ($v) { $v } else { $Default }
}
if (-not $env:TOKEN) { Stop-WithError 'a token is required' }
if (-not $env:DASHBOARD_PASSWORD) { Stop-WithError 'a dashboard password is required' }
$lines = @(
    "# Generated by XDeck from the app's settings; changes here are overwritten."
    "bindPort = $(Get-Setting 'BIND_PORT' '7000')"
    'auth.method = "token"'
    "auth.token = $(ConvertTo-TomlString $env:TOKEN)"
    "vhostHTTPPort = $(Get-Setting 'VHOST_HTTP_PORT' '8080')"
    "vhostHTTPSPort = $(Get-Setting 'VHOST_HTTPS_PORT' '8443')"
)
if ($env:SUBDOMAIN_HOST) { $lines += "subDomainHost = $(ConvertTo-TomlString $env:SUBDOMAIN_HOST)" }
if ($env:ALLOW_PORTS) {
    $ranges = foreach ($p in ($env:ALLOW_PORTS -split ',' | Where-Object { $_.Trim() })) {
        $p = $p.Trim()
        if ($p -match '^(\d+)-(\d+)$') { "{ start = $($Matches[1]), end = $($Matches[2]) }" }
        elseif ($p -match '^\d+$') { "{ single = $p }" }
        else { Stop-WithError "invalid port or range in ALLOW_PORTS: $p" }
    }
    $lines += "allowPorts = [$($ranges -join ', ')]"
}
$lines += @(
    "webServer.addr = $(ConvertTo-TomlString (Get-Setting 'DASHBOARD_BIND' '127.0.0.1'))"
    "webServer.port = $(Get-Setting 'DASHBOARD_PORT' '7500')"
    "webServer.user = $(ConvertTo-TomlString (Get-Setting 'DASHBOARD_USER' 'admin'))"
    "webServer.password = $(ConvertTo-TomlString $env:DASHBOARD_PASSWORD)"
    'log.to = "console"'
)
Write-TextFile $Conf (($lines -join "`n") + "`n")
Invoke-Native $Bin @('verify', '-c', $Conf)
Write-Step 'Wrote conf\frps.toml'
